"""Technical sprite packing only. Artwork is generated by imagegen, never this script.

Preserves the source PNG. Packs four registered cells at the requested native
resolutions with nearest-neighbor sampling and a binary transparent edge.
Developer-only dependency: Pillow; gameplay and gallery need no Python.
"""
import json
import base64
from pathlib import Path
from PIL import Image

ROOT = Path(__file__).resolve().parent.parent
DEST = ROOT / 'assets/livestock/fish/clownfish'
source = Image.open(DEST / 'clownfish-benchmark-v1-source.png').convert('RGBA')
cell_w, cell_h = source.width // 2, source.height // 2
frames, rects = [], []
for row in range(2):
    for col in range(2):
        cell = source.crop((col*cell_w, row*cell_h, (col+1)*cell_w, (row+1)*cell_h))
        alpha = cell.getchannel('A').point(lambda a: 255 if a >= 128 else 0)
        bounds = alpha.getbbox()
        if bounds is None:
            raise ValueError('Empty generated frame')
        cell.putalpha(alpha)
        frames.append(cell.crop(bounds))
        rects.append(list(bounds))
max_w = max(f.width for f in frames)
max_h = max(f.height for f in frames)
manifest = json.loads((DEST / 'benchmark-v1.json').read_text(encoding='utf-8'))
manifest['sourceDimensions'] = list(source.size)
manifest['sourceFrameBounds'] = rects
manifest['atlases'] = {}
manifest['normalization'] = 'Developer packing: alpha threshold 128, nearest-neighbor sampling, uniform scale across four frames, centered transparent padding. Original generated source is preserved.'
for size in [96, 128, 192, 256]:
    atlas = Image.new('RGBA', (size*4, size))
    scale = size*.875 / max(max_w, max_h)
    for index, frame in enumerate(frames):
        frame = frame.resize((round(frame.width*scale), round(frame.height*scale)), Image.Resampling.NEAREST)
        atlas.paste(frame, (index*size+(size-frame.width)//2, (size-frame.height)//2))
    name = f'clownfish-benchmark-v1-{size}.png'
    atlas.save(DEST / name)
    bounds = [list(atlas.crop((i*size, 0, (i+1)*size, size)).getchannel('A').getbbox()) for i in range(4)]
    manifest['atlases'][str(size)] = {'file': name, 'frameWidth': size, 'frameHeight': size, 'columns': 4, 'rows': 1, 'bounds': bounds}
    assert atlas.getchannel('A').getextrema() == (0, 255)
    assert set(atlas.getchannel('A').getdata()).issubset({0, 255})
(DEST / 'benchmark-v1.json').write_text(json.dumps(manifest, indent=2)+'\n', encoding='utf-8')
(DEST / 'benchmark-v1.js').write_text('"use strict";\nwindow.ART_BENCHMARK = '+json.dumps(manifest, indent=2)+';\n', encoding='utf-8')
if manifest.get('installed'):
    # Embedded local PNG keeps canvas thumbnail/export origin-clean under file://.
    payload = {
        'speciesId': 'clown', 'scientificName': 'Amphiprion ocellaris',
        'assetId': manifest['id'], 'frameSize': 128,
        'bounds': manifest['atlases']['128']['bounds'],
        'eyes': [[104,60],[104,59.5],[103.5,59.5],[105,59.5]],
        'src': 'data:image/png;base64,'+base64.b64encode((DEST / manifest['atlases']['128']['file']).read_bytes()).decode('ascii')
    }
    (ROOT / 'js/clownfish-art.js').write_text('"use strict";\nAL.LivestockArt = {clown: '+json.dumps(payload)+'};\n', encoding='utf-8')
print('Packed 4 transparent native-resolution atlases; source preserved.')
